import fs from 'node:fs';import path from 'node:path';import assert from 'node:assert/strict';
import {hash,json} from './bounded-source-hash-20261026.mjs';import {clonePinnedWebsite} from './clone-pinned-website-stage-20261026.mjs';
const proposalRoot='F:/VisibleMedicine/staging/20261026-workbook-history-proposal',proposalFile=proposalRoot+'/PROPOSAL.json',proposal=json(proposalFile);
assert.equal(hash(proposalFile),'9253fae409f357d0aa87cdb2112870c5ec77c73d1902bbdde3f37723fdff7f0c');
assert.equal(hash(proposalRoot+'/'+proposal.proposal.component),proposal.proposal.componentSha256);assert.equal(hash(proposalRoot+'/'+proposal.proposal.test),proposal.proposal.testSha256);
assert.equal(hash(proposalRoot+'/'+proposal.original.path),proposal.original.sha256);
assert(json('F:/VisibleMedicine/staging/20261026-workbook-history-browser/TERMINAL.json').graceful);
const stage='F:/VisibleMedicine/staging/20261026-workbook-history-website';
const {parent,site}=clonePinnedWebsite({stage,parentFile:proposal.sourceReceipt,parentSha256:proposal.sourceReceiptSha256});
const component='components/EducationRuntime.tsx',test='tests/workbook-draft-navigation.test.mjs',doc='docs/WORKBOOK_DRAFT_HISTORY.md';
assert.equal(hash(site+'/'+component),proposal.original.sha256);fs.copyFileSync(proposalRoot+'/'+proposal.proposal.component,site+'/'+component);
let text=fs.readFileSync(proposalRoot+'/'+proposal.proposal.test,'utf8');
const changes=[["import {pathToFileURL} from 'node:url';","import {pathToFileURL, fileURLToPath} from 'node:url';"],["const site=process.env.WORKBOOK_SITE_ROOT;\nassert(site,'WORKBOOK_SITE_ROOT is required');","const site=process.env.WORKBOOK_SITE_ROOT??fileURLToPath(new URL('../',import.meta.url));"]];
for(const [from,to]of changes){assert.equal(text.split(from).length,2);text=text.replace(from,to);}
fs.writeFileSync(site+'/'+test,text,{flag:'wx'});
let inverse=text;for(const[from,to]of [...changes].reverse())inverse=inverse.replace(to,from);assert.equal(inverse,fs.readFileSync(proposalRoot+'/'+proposal.proposal.test,'utf8'),'All regression assertions must remain exact');
fs.writeFileSync(site+'/'+doc,`# Workbook draft history protection\n\nImaging teaching and assessment workbook drafts now use the same native history guard as lecture drafts. Cancelling a cancellable same-document browser Back or Forward keeps the editor and unsaved content. Choosing to leave proceeds. A successful draft save refreshes the guard so clean navigation does not warn.\n\nThe existing content-change warning and external-link protection remain. The guard uses committed dirty state, cleans up on unmount, and never adds sentinel history or rewrites the router. Browsers without the optional cancellable Navigation API retain link and unload protection; noncancellable traversal is not intercepted. This does not add draft persistence or save content automatically.\n\nVerification covers actual WorkbookBuilder with synthetic data and browser-native traversal, plus whole regression roots. Synthetic save responses and prompt choices do not establish real-account or database acceptance. Existing publication, review, entitlement and source-data boundaries are unchanged.\n`,{flag:'wx'});
for(const p of ['next-env.d.ts','.next/types/routes.d.ts']){const from='F:/VisibleMedicine/staging/20261026-surface-recovery-website/website/'+p,to=site+'/'+p;if(!fs.existsSync(to)){fs.mkdirSync(path.dirname(to),{recursive:true});fs.copyFileSync(from,to,fs.constants.COPYFILE_EXCL);}assert.equal(hash(from),hash(to));}
const review=json(site+'/atlas-review/integration-inputs.json');assert(!review.inputs.some(r=>r.path===component));for(const r of review.inputs)assert.equal(hash(site+'/'+r.path),r.sha256,r.path);
const rows=parent.sourceRows.map(r=>{const actual=hash(site+'/'+r.path);assert.equal(actual,r.path===component?proposal.proposal.componentSha256:r.sha256,r.path);return {...r,sha256:actual,bytes:fs.statSync(site+'/'+r.path).size}});
for(const p of [test,doc]){assert(!rows.some(r=>r.path===p));rows.push({path:p,sha256:hash(site+'/'+p),bytes:fs.statSync(site+'/'+p).size});}rows.sort((a,b)=>a.path.localeCompare(b.path));
const source={schema:'vm-workbook-draft-history-successor/1',at:new Date().toISOString(),website:site,atlas:parent.atlas,atlasHead:parent.atlasHead,atlasTree:parent.atlasTree,parent:proposal.sourceReceipt,parentSha256:proposal.sourceReceiptSha256,sourceRows:rows,sourcePaths:rows.length,changedPaths:[component],newPaths:[test,doc],dependencies:parent.dependencies,reviewBindingSha256:parent.reviewBindingSha256,proposal:{path:proposalFile,sha256:hash(proposalFile)},portableTestRootOnlyAdaptation:changes,allOriginalTestsUnchanged:true,normalPreviewChanged:false,clinicalApproval:false};
fs.writeFileSync(stage+'/SOURCE_CANDIDATE.json',JSON.stringify(source,null,2)+'\n',{flag:'wx'});
console.log(JSON.stringify({source:stage+'/SOURCE_CANDIDATE.json',sha256:hash(stage+'/SOURCE_CANDIDATE.json'),paths:rows.length,protectedReviewPaths:review.inputs.length}));
